var COMP={A:'T',T:'A',C:'G',G:'C'};
function complement(s){ return String(s).toUpperCase().replace(/[^ACGT]/g,'').split('').map(function(c){return COMP[c];}).join(''); }
function reverseComplement(s){ return complement(s).split('').reverse().join(''); }
function transcribe(s){ return String(s).toUpperCase().replace(/T/g,'U'); }
function reverseTranscribe(rna){ return String(rna).toUpperCase().replace(/U/g,'T'); }
function gcContent(s){ s=String(s).toUpperCase().replace(/[^ACGT]/g,''); if(!s.length) return null; var gc=0; for(var i=0;i<s.length;i++) if(s[i]==='G'||s[i]==='C') gc++; return gc/s.length; }
function isValidDNA(s){ return /^[ACGTacgt]+$/.test(s); }
var EXPORTS={ complement:complement, reverseComplement:reverseComplement, transcribe:transcribe, reverseTranscribe:reverseTranscribe, gcContent:gcContent, isValidDNA:isValidDNA };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DNAForgePure = EXPORTS; }
